  <script>
    // Utility to normalise Eastern/Persian digits to Western digits
    function toWesternDigits(str) {
      return str
        .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
        .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
    }

    const inputs = Array.from(document.querySelectorAll('.otp-box'));
    const verifyBtn = document.getElementById('btn-submit');
    const timerDisplay = document.getElementById('timer-display');
    const countdownWrapper = document.getElementById('countdown-wrapper');
    const resendBtn = document.getElementById('btn-resend');
    const toast = document.getElementById('toast');
    const toastMessage = document.getElementById('toast-message');

    let remainingSeconds = 45;
    let timerInterval = null;

    function updateSubmitState() {
      const code = inputs.map(i => i.value).join('');
      verifyBtn.disabled = code.length !== 6;
    }

    // Input navigation & digit handling
    inputs.forEach((input, index) => {
      input.addEventListener('input', (e) => {
        let val = toWesternDigits(e.target.value).replace(/\D/g, '');

        if (val.length > 1) {
          val = val.slice(-1);
        }

        input.value = val;
        input.classList.toggle('filled', val !== '');

        if (val && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
        updateSubmitState();
      });

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && !input.value && index > 0) {
          inputs[index - 1].focus();
        } else if (e.key === 'ArrowRight' && index < inputs.length - 1) {
          inputs[index + 1].focus();
        } else if (e.key === 'ArrowLeft' && index > 0) {
          inputs[index - 1].focus();
        }
      });

      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const pastedData = (e.clipboardData || window.clipboardData).getData('text');
        const digits = toWesternDigits(pastedData).replace(/\D/g, '').slice(0, 6);

        if (digits) {
          digits.split('').forEach((digit, i) => {
            if (inputs[i]) {
              inputs[i].value = digit;
              inputs[i].classList.add('filled');
            }
          });
          const nextIndex = Math.min(digits.length, inputs.length - 1);
          inputs[nextIndex].focus();
          updateSubmitState();
        }
      });
    });

    // Countdown Timer logic
    function startCountdown(seconds) {
      clearInterval(timerInterval);
      remainingSeconds = seconds;
      countdownWrapper.style.display = 'inline';
      resendBtn.style.display = 'none';

      const updateUI = () => {
        const mins = Math.floor(remainingSeconds / 60);
        const secs = remainingSeconds % 60;
        timerDisplay.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;

        if (remainingSeconds <= 0) {
          clearInterval(timerInterval);
          countdownWrapper.style.display = 'none';
          resendBtn.style.display = 'inline';
        }
        remainingSeconds--;
      };

      updateUI();
      timerInterval = setInterval(updateUI, 1000);
    }

    // Resend button trigger
    resendBtn.addEventListener('click', () => {
      // Clear inputs
      inputs.forEach(i => {
        i.value = '';
        i.classList.remove('filled');
      });
      inputs[0].focus();
      updateSubmitState();

      // Show toast
      showToast('تم إرسال رمز تحقق جديد بنجاح');

      // Restart 45-second timer
      startCountdown(45);
    });

    // Verification button action
    verifyBtn.addEventListener('click', () => {
      const code = inputs.map(i => i.value).join('');
      verifyBtn.disabled = true;
      verifyBtn.innerHTML = '<span>جاري التحقق...</span>';

      setTimeout(() => {
        showToast('تم تأكيد الرمز بنجاح');
        verifyBtn.innerHTML = '<span>تم التحقق</span>';
        verifyBtn.style.backgroundColor = '#059669';
      }, 1000);
    });

    function showToast(msg) {
      toastMessage.textContent = msg;
      toast.classList.add('show');
      setTimeout(() => {
        toast.classList.remove('show');
      }, 3500);
    }

    // Start initial timer
    startCountdown(45);
  </script>
